"""Three existing peak witnesses only. CPU reconstruction, no native model/init."""
import json,hashlib,datetime,importlib.util
from pathlib import Path
import numpy as np
P=Path(__file__).resolve().parents[1];R=P/'runs/two_panel_full_38'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
baseline_path=P/'runtime_ipc/full_38-cloth-material-baseline.json';baseline=json.loads(baseline_path.read_text());cfg=json.loads((R/'config.json').read_text());rest=dict(np.load(R/'rest.npz'));raw=dict(np.load(R/'states.npz'));asset=dict(np.load(R/'source/assets'/cfg['bag']['npz_file']));keep=np.r_[np.diff(raw['time'])>1e-9,True];times=raw['time'][keep];positions=raw['bag'][keep];faces=rest['bag_faces'];assert np.array_equal(faces,asset['faces'])
spec=importlib.util.spec_from_file_location('old_pure_baseline',P/'runtime_ipc/full30_cloth_material_baseline.py');m=importlib.util.module_from_spec(spec);spec.loader.exec_module(m)
frontids=np.flatnonzero(np.isin(faces,asset['handle_front']).all(1));grid,width,along=m.reconstruction_strip(asset,frontids,'front',{});uv=np.full((len(rest['bag']),2),np.nan);uv[grid]=np.stack(np.meshgrid(width,along),axis=-1)
buv=np.full_like(uv,np.nan);buv[asset['panel_back_grid']]=np.stack(np.meshgrid(asset['material_x'],asset['material_height']),axis=-1)
selected=[('held_handle_max_principal','handle_front','principal_max',uv),('held_handle_max_construction_length','handle_front','length_ratio',uv),('back_panel_max_principal','panel_back','principal_max',buv)]
rows=[];paths=[baseline_path,R/'config.json',R/'rest.npz',R/'states.npz',R/'source/assets'/cfg['bag']['npz_file'],R/'source/physics_config.py',R/'source/scene.py',P/'runtime_ipc/full30_cloth_material_baseline.py'];hashes={str(p):sha(p) for p in paths}
for label,region,metric,coords in selected:
 w=baseline['groups'][region]['periods']['entire_run']['extrema'][metric];i=w['saved_frame_index'];fi=w['native_and_source_face_index'];assert abs(times[i]-w['time_s'])<1e-8;ids=faces[fi];p0=rest['bag'][ids];p=positions[i,ids];e0=(p0[1:]-p0[0]).T;e=(p[1:]-p[0]).T;n=np.cross(e0[:,0],e0[:,1]);n/=np.linalg.norm(n);target=np.array([0.,0.,1.]);v=np.cross(n,target);co=float(n@target);K=np.array([[0.,-v[2],v[1]],[v[2],0.,-v[0]],[-v[1],v[0],0.]]);rot=np.eye(3)+K+K@K/(1+co) if co!=-1 else np.diag([-1.,-1.,1.]);Dm=(rot@e0)[:2];F=e@np.linalg.inv(Dm);F0=e0@np.linalg.inv(Dm);C=F.T@F;length=np.sqrt(np.diag(C));corr=C[0,1]/np.prod(length);sval=np.linalg.svd(F,compute_uv=False);cc=coords[ids];dc=(cc[1:]-cc[0]).T;refdirs=e0@np.linalg.inv(dc);dirs=e@np.linalg.inv(dc);ratios=np.linalg.norm(dirs,axis=0)/np.linalg.norm(refdirs,axis=0);angle=lambda z:np.degrees(np.arccos(np.clip(np.dot(z[:,0],z[:,1])/np.prod(np.linalg.norm(z,axis=0)),-1,1)));refunits=refdirs/np.linalg.norm(refdirs,axis=0);nativecomponents=(rot@refunits)[:2];q=100.;lam=cfg['bag']['E']*2*cfg['bag']['thickness']/(1-cfg['bag']['nu']**2);mu=cfg['bag']['handle_shear_stiffness'] if region.startswith('handle') else cfg['bag']['shear_stiffness'];eps=length-1;ws=lam*np.sum(eps**2+q*np.maximum(eps,0)**3);wsh=mu*C[0,1]**2
 r={'label':label,'time_s':float(times[i]),'phase':w['phase_at_time'],'face_index':fi,'vertex_indices':ids.tolist(),'reference_area_m2':float(np.linalg.norm(np.cross(e0[:,0],e0[:,1]))/2),'native_chart_rest_orthonormal_error':float(np.linalg.norm(F0.T@F0-np.eye(2))),'native_chart_a_b_lengths':length.tolist(),'native_chart_a_b_extension_percent':(100*eps).tolist(),'native_C':C.tolist(),'native_chart_a_b_angle_deg':float(np.degrees(np.arccos(np.clip(corr,-1,1)))),'native_chart_angle_change_deg':float(np.degrees(np.arccos(np.clip(corr,-1,1)))-90),'principal_stretches':sval.tolist(),'area_ratio':float(np.prod(sval)),'construction_width_length_ratios':ratios.tolist(),'construction_width_length_extension_percent':(100*(ratios-1)).tolist(),'construction_angle_change_deg':float(angle(dirs)-angle(refdirs)),'construction_axis_components_in_native_rest_chart':nativecomponents.tolist(),'pure_angle_normalized_column_metric_principal_stretches':np.sqrt(np.linalg.eigvalsh([[1,corr],[corr,1]]))[::-1].tolist(),'pure_angle_diagnostic_scope':'Algebraic normalization of columns at the measured state; not additive strain attribution, new physical state or predicted equilibrated shape.','reconstructed_energy_density_N_m':{'stretch':float(ws),'shear':float(wsh),'lambda':lam,'mu':mu,'strain_rate_assumed_default':q},'fixed_deformation_E20MPa_energy_density_N_m':{'stretch':float(2*ws),'shear':float(wsh),'scope':'Exact coefficient scaling at this frozen F only, not a response/force-equilibrium prediction.'}}
 if label=='held_handle_max_construction_length':assert abs(ratios[1]-w['value'])<1e-9
 else:assert abs(max(sval)-w['value'])<1e-9
 rows.append(r)
out={'kind':'bounded_full38_three_peak_native_chart_reconstruction','created_utc':datetime.datetime.now(datetime.timezone.utc).isoformat(),'run':str(R),'native_simulation_performed':False,'new_policy_applied':False,'rows':rows,'native_chart_method':'Exact pinned source formula: rest normal rotates to world+Z with Rodrigues R, Dm=(R*rest_edges).xy; F=current_edges*inverse(Dm), a=(1,0),b=(0,1). Texture UV and first-edge chart are not used for native energy.','limits':['Three already-declared extrema only, not exhaustive native-axis maxima over the full run.','Construction directions and native chart axes are neither measured warp nor weft yarns.','Pure-angle normalized metric is explanatory algebra, not percentage decomposition or a simulated state.','Reported energies assume unchanged native strain_rate default100; no present-run numerical rate buffer was archived.','Higher E changes forces/shape/contact even when scalar D and mu remain unchanged; no linear displacement prediction.'],'input_sha256':hashes,'inputs_unchanged':all(sha(Path(p))==v for p,v in hashes.items())}
p=P/'runtime_ipc/full38-three-peak-native-axis-review.json';assert not p.exists();p.write_text(json.dumps(out,indent=2,allow_nan=False)+'\n');print(json.dumps({'output':str(p),'sha256':sha(p),'rows':[{k:r[k] for k in ['label','face_index','native_chart_a_b_extension_percent','construction_width_length_extension_percent','construction_angle_change_deg','principal_stretches','area_ratio','reconstructed_energy_density_N_m','pure_angle_normalized_column_metric_principal_stretches','construction_axis_components_in_native_rest_chart']} for r in rows]},indent=2))
